mapper.select:
select * from ( select d.ID, d.TWINING_DISC_CODE, d.TWINING_DISC_NAME, d.STATUS, d.PRO_SIZE, d.QTY, d.SORT_TYPE, d.FACTORY_CODE, d.DATA_SOURCE, d.IS_DELETE, d.CREATE_BY, d.CREATE_TIME, d.UPDATE_BY, d.UPDATE_TIME, d.REMARK, (select count(1) from T_GSQ_TWINING_DISC_SPEC s where s.TWINING_DISC_CODE = d.TWINING_DISC_CODE and s.IS_DELETE = '0') as SPEC_COUNT, (select count(1) from T_GSQ_TWINING_DISC_MACHINE m where m.TWINING_DISC_CODE = d.TWINING_DISC_CODE and m.IS_DELETE = '0') as MACHINE_COUNT from T_GSQ_TWINING_DISC d where d.IS_DELETE = '0'
and INSTR(d.TWINING_DISC_CODE, #{twiningDiscCode}) > 0
and INSTR(d.TWINING_DISC_NAME, #{twiningDiscName}) > 0
and d.STATUS = #{status}
and INSTR(d.SORT_TYPE, #{sortType}) > 0
and d.FACTORY_CODE = #{factoryCode}
and d.DATA_SOURCE = #{dataSource}
order by d.CREATE_TIME desc
) t
order by ${orderStr}

select count(1)
from T_GSQ_TWINING_DISC
where IS_DELETE = '0'
  and TWINING_DISC_CODE = #{twiningDiscCode}

    and ID != #{id}
